CREATE TABLE catalog_options(category text NOT NULL,key text NOT NULL,label text NOT NULL,active boolean NOT NULL DEFAULT true,revision integer NOT NULL DEFAULT 1,PRIMARY KEY(category,key));
CREATE UNIQUE INDEX catalog_labels ON catalog_options(category,lower(label));
CREATE TABLE entity_sequences(entity text NOT NULL,year integer NOT NULL,value integer NOT NULL,PRIMARY KEY(entity,year));
CREATE TABLE employees(id text PRIMARY KEY,code text NOT NULL UNIQUE,first_name text NOT NULL,last_name text NOT NULL,email text NOT NULL DEFAULT '',phone text NOT NULL DEFAULT '',role_key text NOT NULL DEFAULT 'operator',skills text NOT NULL DEFAULT '',hourly_cents integer CHECK(hourly_cents>=0),status text NOT NULL DEFAULT 'active' CHECK(status IN ('active','inactive')),revision integer NOT NULL DEFAULT 1,deleted_at timestamptz);
ALTER TABLE crews ADD COLUMN revision integer NOT NULL DEFAULT 1;
ALTER TABLE crews ADD COLUMN deleted_at timestamptz;
ALTER TABLE crews ADD COLUMN shift_start text NOT NULL DEFAULT '08:00';
ALTER TABLE crews ADD COLUMN shift_end text NOT NULL DEFAULT '17:00';
ALTER TABLE crews ADD COLUMN break_minutes integer NOT NULL DEFAULT 30;
CREATE TABLE crew_employees(crew_id text NOT NULL REFERENCES crews(id),employee_id text NOT NULL REFERENCES employees(id),duty text NOT NULL,PRIMARY KEY(crew_id,employee_id));
ALTER TABLE visits ADD COLUMN revision integer NOT NULL DEFAULT 1;
ALTER TABLE visits ADD COLUMN deleted_at timestamptz;
ALTER TABLE visits ADD COLUMN title text NOT NULL DEFAULT '';
ALTER TABLE visits ADD COLUMN planned_minutes integer;
ALTER TABLE visits ADD COLUMN travel_minutes integer NOT NULL DEFAULT 0;
ALTER TABLE visits ADD COLUMN service_key text;
ALTER TABLE visits ADD COLUMN cancellation_reason text NOT NULL DEFAULT '';
ALTER TABLE visits ADD COLUMN cost_complete boolean NOT NULL DEFAULT true;
ALTER TABLE visits ADD COLUMN planned_labor_hourly_cents integer;
UPDATE visits v SET title=c.service,planned_minutes=c.estimated_minutes FROM contracts c WHERE v.contract_id=c.id;
CREATE TABLE visit_personnel(visit_id text NOT NULL REFERENCES visits(id),employee_id text NOT NULL REFERENCES employees(id),name_snapshot text NOT NULL,duty text NOT NULL,hourly_cents integer,actual_minutes integer,PRIMARY KEY(visit_id,employee_id));
CREATE TABLE visit_tasks(id text PRIMARY KEY,visit_id text NOT NULL REFERENCES visits(id),service_key text NOT NULL,description text NOT NULL,element_id text REFERENCES property_elements(id),employee_id text REFERENCES employees(id),quantity numeric NOT NULL CHECK(quantity>0),unit text NOT NULL,completed_quantity numeric CHECK(completed_quantity>=0),status text NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','done','blocked')),notes text NOT NULL DEFAULT '');
CREATE TABLE visit_cost_lines(id text PRIMARY KEY,visit_id text NOT NULL REFERENCES visits(id),category text NOT NULL CHECK(category IN ('materials','equipment','travel','overhead')),description text NOT NULL,quantity numeric NOT NULL CHECK(quantity>0),unit_price_cents integer NOT NULL CHECK(unit_price_cents>=0),total_cents integer NOT NULL CHECK(total_cents>=0));
INSERT INTO visit_cost_lines SELECT md5(id||'-materials'),id,'materials','Importe histórico registrado',1,materials_cents,materials_cents FROM visits WHERE materials_cents>0;
INSERT INTO visit_cost_lines SELECT md5(id||'-equipment'),id,'equipment','Importe histórico registrado',1,equipment_cents,equipment_cents FROM visits WHERE equipment_cents>0;
INSERT INTO visit_cost_lines SELECT md5(id||'-travel'),id,'travel','Importe histórico registrado',1,travel_cents,travel_cents FROM visits WHERE travel_cents>0;
INSERT INTO visit_cost_lines SELECT md5(id||'-overhead'),id,'overhead','Importe histórico registrado',1,overhead_cents,overhead_cents FROM visits WHERE overhead_cents>0;
CREATE TABLE invoices(id text PRIMARY KEY,number text NOT NULL UNIQUE,customer_id text NOT NULL REFERENCES customers(id),property_id text REFERENCES properties(id),issue_date date NOT NULL,due_date date NOT NULL,status text NOT NULL DEFAULT 'draft' CHECK(status IN ('draft','issued','void')),total_cents integer NOT NULL CHECK(total_cents>=0),notes text NOT NULL DEFAULT '',revision integer NOT NULL DEFAULT 1,deleted_at timestamptz);
CREATE TABLE invoice_lines(id text PRIMARY KEY,invoice_id text NOT NULL REFERENCES invoices(id),description text NOT NULL,quantity numeric NOT NULL CHECK(quantity>0),unit_price_cents integer NOT NULL CHECK(unit_price_cents>=0),total_cents integer NOT NULL CHECK(total_cents>=0));
CREATE TABLE payments(id text PRIMARY KEY,invoice_id text NOT NULL REFERENCES invoices(id),received_date date NOT NULL,amount_cents integer NOT NULL CHECK(amount_cents>0),method text NOT NULL,reference text NOT NULL DEFAULT '',voided_at timestamptz,void_reason text NOT NULL DEFAULT '');
CREATE INDEX visit_tasks_visit ON visit_tasks(visit_id);
CREATE INDEX visit_personnel_employee ON visit_personnel(employee_id);
CREATE INDEX invoice_customer ON invoices(customer_id);
CREATE INDEX invoice_payments ON payments(invoice_id);
ALTER TABLE properties DROP CONSTRAINT properties_kind_check;
ALTER TABLE property_zones DROP CONSTRAINT property_zones_unit_check;
ALTER TABLE property_zones DROP CONSTRAINT property_zones_measurement_status_check;
