ALTER TABLE visits ADD COLUMN cancelled_at timestamptz;
ALTER TABLE service_audit ADD COLUMN actor text NOT NULL DEFAULT '';
CREATE TABLE change_history(id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,entity text NOT NULL,entity_id text NOT NULL,event text NOT NULL,actor text NOT NULL,details jsonb NOT NULL,occurred_at timestamptz NOT NULL DEFAULT now());
ALTER TABLE catalog_options ADD COLUMN semantic_key text;
UPDATE catalog_options SET semantic_key=key WHERE category IN ('service','element_kind');
UPDATE visits v SET planned_labor_hourly_cents=c.workers*c.hourly_cents FROM crews c WHERE v.crew_id=c.id AND v.planned_labor_hourly_cents IS NULL;
ALTER TABLE contracts ADD COLUMN service_key text;
